import heapq
from collections import defaultdict

def dijkstra(n, edges, start, swerc_banks):
    graph = defaultdict(list)
    for a, b, c in edges:
        graph[a].append((b, c))
        graph[b].append((a, c))

    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if u in swerc_banks and v in swerc_banks:
                continue
            new_d = d + w
            if new_d < dist[v]:
                dist[v] = new_d
                heapq.heappush(pq, (new_d, v))

    return dist

def find_max_fee(N, P, X, Y, edges, M, swerc_banks):
    max_fee = max(c for _, _, c in edges)
    min_dist = float('inf')

    for fee in range(max_fee, 0, -1):
        new_edges = []
        for a, b, c in edges:
            if a in swerc_banks or b in swerc_banks:
                new_edges.append((a, b, c + fee))
            else:
                new_edges.append((a, b, c))

        dist = dijkstra(N, new_edges, X, swerc_banks)
        if dist[Y] < min_dist:
            min_dist = dist[Y]
        elif dist[Y] == min_dist:
            break

    if min_dist == float('inf'):
        return "Impossible"
    elif min_dist == 0:
        return "Infinity"
    else:
        return min_dist

