import sys
from collections import defaultdict, deque

def find(parent, i):
    if parent[i] == i:
        return i
    parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)

    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def kruskal(graph, n, m, swerc_banks):
    edges = []
    for u, v, w in graph:
        edges.append((w, u, v))

    edges.sort()
    parent = [i for i in range(n + 1)]
    rank = [0] * (n + 1)
    max_fee = 0

    for weight, u, v in edges:
        if find(parent, u) != find(parent, v):
            if u in swerc_banks and v in swerc_banks:
                continue
            union(parent, rank, u, v)
            max_fee = weight

    return max_fee

def can_transfer_with_fee(graph, n, m, swerc_banks, fee):
    visited = set()
    queue = deque([swerc_banks[0]])
    while queue:
        node = queue.popleft()
        if node == swerc_banks[-1]:
            return True
        visited.add(node)
        for neighbor, _ in graph[node]:
            if neighbor not in visited and neighbor not in swerc_banks:
                queue.append(neighbor)
